const fv = (m, x) => (m.unit === 'num2' ? (typeof x === 'number' ? fmtNum(x, 2) : '—') : fmtV(m, x));
const fd = (m, d) => (m.unit === 'num2' ? (typeof d === 'number' ? (d > 0 ? '+' : d < 0 ? '−' : '') + fmtNum(Math.abs(d), 2) : '—') : fmtDelta(m, d));
